INSERT INTO scheduled_tasks (id, agent_id, name, description, schedule_type, cron_expression, action, action_params, status, last_run, next_run, run_count, fail_count, created_at, enabled) VALUES
('ceo-morning-scan', 'ceo-strategic', 'Morning Strategic Scan', 'Quick strategic posture check via LifeOS tools', 'cron', '30 7 * * *', 'custom_prompt', '{"prompt":"Execute Morning Strategic Scan. Step 1: Call lifeos_context_card with agent=strategic for quick snapshot. Step 2: Call lifeos_okrs_progress for OKR status. Step 3: Call lifeos_project_health for portfolio health. Step 4: Call lifeos_directives_risks for risk check. If all clear: reply HEARTBEAT_OK. If findings: produce 3-bullet strategic brief. Escalate P1 or Critical risks to Board Chair via notify.telegram immediately.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('ceo-weekly-review', 'ceo-strategic', 'Weekly Strategic Review', 'Deep weekly strategic assessment with cross-domain synthesis', 'cron', '0 8 * * 1', 'custom_prompt', '{"prompt":"Execute Weekly Strategic Review. Step 1: Call lifeos_okrs_progress for detailed OKR status. Step 2: Call lifeos_project_health for portfolio health with deltas. Step 3: Call lifeos_directives_risks for full risk landscape. Step 4: Call lifeos_opportunities_strengths for opportunity pipeline. Step 5: Call lifeos_alignment for goal-to-project alignment. Step 6: Call lifeos_journal_synthesis with period=past_week for cross-domain patterns. Step 7: Call lifeos_weekly_review for weekly synthesis. Produce: 1) Strategic posture summary in 3 to 5 bullets, 2) Top 3 priorities for the week, 3) Board meeting recommendations if needed, 4) Write systemic_journal entries for any cross-domain patterns detected. Escalate urgent items to Board Chair.","priority":"P2"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('ceo-monthly-session', 'ceo-strategic', 'Monthly Strategy Session', 'Monthly strategic recalibration with temporal analysis', 'cron', '0 9 1 * *', 'custom_prompt', '{"prompt":"Execute Monthly Strategy Session. Step 1: Call lifeos_monthly_synthesis for monthly rollup. Step 2: Call lifeos_temporal_analysis with period=past_month for temporal patterns. Step 3: Call lifeos_correlate with period=past_month for cross-domain correlations. Step 4: Call lifeos_okrs_progress for OKR trajectory. Step 5: Call lifeos_project_health for portfolio trends. Assess: 1) Are we on track for quarterly OKRs? 2) Any strategic pivots needed? 3) Resource allocation changes? 4) Board meeting agenda items. Produce monthly strategic brief for Board Chair. Write systemic_journal entries for significant patterns.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1),
('ceo-quarterly-retro', 'ceo-strategic', 'Quarterly Retrospective', 'End-of-quarter strategic assessment with lessons learned', 'cron', '0 10 1 1,4,7,10 *', 'custom_prompt', '{"prompt":"Execute Quarterly Retrospective. Step 1: Call lifeos_quarterly_retrospective for comprehensive assessment. Step 2: Call lifeos_okrs_progress for final OKR status. Step 3: Call lifeos_project_health for portfolio completion rate. Step 4: Call lifeos_temporal_analysis with period=past_quarter for quarterly patterns. Document: 1) What worked this quarter, 2) What did not work, 3) Key learnings, 4) Recommendations for next quarter. Prepare comprehensive brief for Board Chair review. Write systemic_journal entry for quarterly systemic learning.","priority":"P1"}', 'active', 0, 0, 0, 0, (strftime('%s','now')*1000), 1);
